31	#include "resize_bilinear_v2.h"
32	#include "acl/acl.h"
33	
34	using namespace op;
35	
36	#ifdef __cplusplus
37	extern "C" {
38	#endif
39	
40	static constexpr size_t NCHW_DIM_NUM = 4;
41	
42	static constexpr size_t DIM_BATCH_NCHW = 0;
43	static constexpr size_t DIM_CHANNEL_NCHW = 1;
44	static constexpr size_t DIM_HEIGHT_NCHW = 2;
45	static constexpr size_t DIM_WIDTH_NCHW = 3;
46	static constexpr size_t DIM_BATCH_NHWC = 0;
47	static constexpr size_t DIM_HEIGHT_NHWC = 1;
48	static constexpr size_t DIM_WIDTH_NHWC = 2;
49	static constexpr size_t DIM_CHANNEL_NHWC = 3;
50	static constexpr size_t SCALES_SIZE = 2;
51	static constexpr double EPSILON = 1e-5;
52	
53	static const std::initializer_list<op::DataType> DTYPE_SUPPORT_LIST_DATA = {op::DataType::DT_FLOAT16,
54	                                                                            op::DataType::DT_FLOAT};
55	
56	static const std::initializer_list<op::DataType> DTYPE_SUPPORT_LIST_DATA_REGBASE = {
57	    op::DataType::DT_FLOAT16, op::DataType::DT_FLOAT, op::DataType::DT_BF16};
58	
59	static bool CheckShape(const aclTensor* self, const aclFloatArray* scales, const aclTensor* out)
60	{
61	    // The scale parameter is retained for interface consistency and is currently not used in computations.
62	    auto selfShape = self->GetViewShape();
63	    auto outShape = out->GetViewShape();
64	    if (selfShape.GetDimNum() != NCHW_DIM_NUM || outShape.GetDimNum() != NCHW_DIM_NUM) {
65	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The selfShape and outShape must be 4 dim.");
66	        return false;
67	    }
68	    uint64_t size = 0;
69	    auto ret = aclGetFloatArraySize(scales, &size);
70	    if (ret != 0 || size != NCHW_DIM_NUM) {
71	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "aclGetFloatArraySize error, ret=%lu, size=%lu, NCHW_DIM_NUM=%zu.",
72	                static_cast<uint64_t>(ret), size, NCHW_DIM_NUM);
73	        return false;
74	    }
75	
76	    return true;
77	}
78	
79	static bool CheckInputElement(const aclTensor* self, const aclFloatArray* scales, const aclTensor* out, bool extendFlag)
80	{
81	    // The scale parameter is retained for interface consistency and is currently not used in computations.
82	    auto selfShape = self->GetViewShape();
83	    auto outShape = out->GetViewShape();
84	
85	    size_t dimBatch = DIM_BATCH_NCHW;
86	    size_t dimChannel = DIM_CHANNEL_NCHW;
87	    size_t dimHeight = DIM_HEIGHT_NCHW;
88	    size_t dimWidth = DIM_WIDTH_NCHW;
89	
90	    if (extendFlag && self->GetStorageFormat() == op::Format::FORMAT_NHWC) {
91	        dimBatch = DIM_BATCH_NHWC;
92	        dimChannel = DIM_CHANNEL_NHWC;
93	        dimHeight = DIM_HEIGHT_NHWC;
94	        dimWidth = DIM_WIDTH_NHWC;
95	    }
96	
97	    if (selfShape.GetDim(dimBatch) != outShape.GetDim(dimBatch) ||
98	        selfShape.GetDim(dimChannel) != outShape.GetDim(dimChannel)) {
99	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The dim of batch or channel is not matched.");
100	        return false;
101	    }
102	
103	    if (extendFlag) {
104	        int64_t dstDimHeightMax = static_cast<int64_t>(static_cast<double>(selfShape.GetDim(dimHeight)) *
105	                                                       (static_cast<double>((*scales)[dimHeight]) + EPSILON));
106	        int64_t dstDimHeightMin = static_cast<int64_t>(static_cast<double>(selfShape.GetDim(dimHeight)) *
107	                                                       (static_cast<double>((*scales)[dimHeight]) - EPSILON));
108	        if ((outShape.GetDim(dimHeight) < dstDimHeightMin) || (outShape.GetDim(dimHeight) > dstDimHeightMax)) {
109	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The dim of height is not matched.");
110	            return false;
111	        }
112	
113	        int64_t dstDimWidthMax = static_cast<int64_t>(static_cast<double>(selfShape.GetDim(dimWidth)) *
114	                                                      (static_cast<double>((*scales)[dimWidth]) + EPSILON));
115	        int64_t dstDimWidthMin = static_cast<int64_t>(static_cast<double>(selfShape.GetDim(dimWidth)) *
116	                                                      (static_cast<double>((*scales)[dimWidth]) - EPSILON));
117	        if ((outShape.GetDim(dimWidth) < dstDimWidthMin) || (outShape.GetDim(dimWidth) > dstDimWidthMax)) {
118	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The dim of width is not matched.");
119	            return false;
120	        }
121	    }
122	
123	    return true;
124	}
125	
126	static bool CheckNotNull(const aclTensor* self, const aclFloatArray* scales, const char* mode, const aclTensor* out)
127	{
128	    OP_CHECK_NULL(self, return false);
129	    OP_CHECK_NULL(scales, return false);
130	    OP_CHECK_NULL(out, return false);
131	    if (mode == nullptr) {
132	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "mode is null, please check input arguments");
133	        return false;
134	    }
135	    return true;
136	}
137	
138	static bool CheckDtypeValid(const aclTensor* self, const aclTensor* out, bool extendFlag)
139	{
140	    if (extendFlag) {
141	        OP_CHECK_DTYPE_NOT_SUPPORT(self, DTYPE_SUPPORT_LIST_DATA_REGBASE, return false);
142	    } else {
143	        OP_CHECK_DTYPE_NOT_SUPPORT(self, DTYPE_SUPPORT_LIST_DATA, return false);
144	    }
145	    OP_CHECK_DTYPE_NOT_MATCH(out, self->GetDataType(), return false);
146	    return true;
147	}
148	
149	static bool CheckModeStr(const char* mode)
150	{
151	    if (strncmp(mode, "nearest", strlen("nearest")) == 0 || strncmp(mode, "bilinear", strlen("bilinear")) == 0) {
152	        return true;
153	    }
154	    OP_LOGE(ACLNN_ERR_PARAM_INVALID, "CheckModeStr failed, mode:%s", mode);
155	    return false;
156	}
157	
158	static bool CheckFormat(const aclTensor* self, const aclTensor* out, bool extendFlag)
159	{
160	    if (extendFlag) {
161	        auto xFormat = self->GetStorageFormat();
162	        auto yFormat = out->GetStorageFormat();
163	        if (xFormat != yFormat) {
164	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The format of self and out must be same.");
165	            return false;
166	        }
167	
168	        if (xFormat != op::Format::FORMAT_NCHW && xFormat != op::Format::FORMAT_NHWC) {
169	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The format of self must be NCHW or NHWC.");
170	            return false;
171	        }
172	
173	        return true;
174	    }
175	
176	    if (self->GetStorageFormat() != op::Format::FORMAT_NCHW || out->GetStorageFormat() != op::Format::FORMAT_NCHW) {
177	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The format of self or out must be NCHW.");
178	        return false;
179	    }
180	    return true;
181	}
182	
183	static aclnnStatus CheckParams(const aclTensor* self, const aclFloatArray* scales, const char* mode,
184	                               const aclTensor* out, bool extendFlag)
185	{
186	    // 1. 检查参数是否为空指针
187	    CHECK_RET(CheckNotNull(self, scales, mode, out), ACLNN_ERR_PARAM_NULLPTR);
188	    // 2. 检查mode是否支持
189	    CHECK_RET(CheckModeStr(mode), ACLNN_ERR_PARAM_INVALID);
190	    // 3. 检查参数的数据类型是否符合预期
191	    CHECK_RET(CheckDtypeValid(self, out, extendFlag), ACLNN_ERR_PARAM_INVALID);
192	    // 4. 检查输入格式是否为NCHW
193	    CHECK_RET(CheckFormat(self, out, extendFlag), ACLNN_ERR_PARAM_INVALID);
194	    // 5. 检查输入元素是否合法
195	    CHECK_RET(CheckInputElement(self, scales, out, extendFlag), ACLNN_ERR_PARAM_INVALID);
196	    // 6. 检查输入tensor的shape
197	    CHECK_RET(CheckShape(self, scales, out), ACLNN_ERR_PARAM_INVALID);
198	    return ACLNN_SUCCESS;
199	}
200	
201	static const aclTensor* CreateSizesV35(const aclTensor* out, aclOpExecutor* executor)
202	{
203	    auto outShape = op::ToShapeVector(out->GetViewShape());
204	    const aclIntArray* arr = executor->AllocIntArray(outShape.data(), outShape.size());
205	    auto sizes = executor->ConvertToTensor(arr, op::ToOpDataType(ACL_INT32));
206	    return sizes;
207	}
208	
209	static const aclTensor* CreateSizesRegBase(const aclTensor* self, const aclFloatArray* scales, aclOpExecutor* executor)
210	{
211	    uint64_t size = 0;
212	    auto ret = aclGetFloatArraySize(scales, &size);
213	    if (ret != 0) {
214	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "scales is null, please check input arguments of scales");
215	        return nullptr;
216	    }
217	    if (self->GetViewShape().GetDimNum() != size) {
218	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "dim num of self should equal with size of scales, self DimNum=%zu, size=%lu",
219	                self->GetViewShape().GetDimNum(), size);
220	        return nullptr;
221	    }
222	    auto selfShape = self->GetViewShape();
223	    std::vector<int64_t> sizesList(SCALES_SIZE);
224	    auto xFormat = self->GetStorageFormat();
225	    if (xFormat == op::Format::FORMAT_NCHW) {
226	        sizesList[0] = static_cast<int64_t>(static_cast<double>(selfShape.GetDim(DIM_HEIGHT_NCHW)) *
227	                                            static_cast<double>((*scales)[DIM_HEIGHT_NCHW]));
228	        sizesList[1] = static_cast<int64_t>(static_cast<double>(selfShape.GetDim(DIM_WIDTH_NCHW)) *
229	                                            static_cast<double>((*scales)[DIM_WIDTH_NCHW]));
230	    } else {
231	        sizesList[0] = static_cast<int64_t>(static_cast<double>(selfShape.GetDim(DIM_HEIGHT_NHWC)) *
232	                                            static_cast<double>((*scales)[DIM_HEIGHT_NHWC]));
233	        sizesList[1] = static_cast<int64_t>(static_cast<double>(selfShape.GetDim(DIM_WIDTH_NHWC)) *
234	                                            static_cast<double>((*scales)[DIM_WIDTH_NHWC]));
235	    }
236	    const aclIntArray* arr = executor->AllocIntArray(sizesList.data(), sizesList.size());
237	    auto sizes = executor->ConvertToTensor(arr, op::ToOpDataType(ACL_INT32));
238	    return sizes;
239	}
240	
241	static bool GetExtendPathFlag()
242	{
243	    auto curArch = GetCurrentPlatformInfo().GetCurNpuArch();
244	    if (IsRegBase(curArch) || curArch == NpuArch::DAV_2201 || curArch == NpuArch::DAV_1001 ||
245	        curArch == NpuArch::DAV_2002) {
246	        return true;
247	    }
248	    return false;
249	}
250	
251	aclnnStatus aclnnResizeGetWorkspaceSize(const aclTensor* self, const aclFloatArray* scales, const char* mode,
252	                                        aclTensor* out, uint64_t* workspaceSize, aclOpExecutor** executor)
253	{
254	    OP_CHECK_COMM_INPUT(workspaceSize, executor);
255	
256	    L2_DFX_PHASE_1(aclnnResize, DFX_IN(self, scales, mode), DFX_OUT(out));
257	    // 参数检查
258	    bool extendFlag = GetExtendPathFlag();
259	
260	    auto ret = CheckParams(self, scales, mode, out, extendFlag);
261	    CHECK_RET(ret == ACLNN_SUCCESS, ret);
262	    // 创建OpExecutor
263	    auto uniqueExecutor = CREATE_EXECUTOR();
264	    CHECK_RET(uniqueExecutor.get() != nullptr, ACLNN_ERR_INNER_CREATE_EXECUTOR);
265	
266	    auto selfContiguous = l0op::Contiguous(self, uniqueExecutor.get());
267	    CHECK_RET(selfContiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
268	
269	    auto outContiguous = l0op::Contiguous(out, uniqueExecutor.get());
270	    CHECK_RET(outContiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
271	
272	    if (extendFlag && IsRegBase()) {
273	        auto sizes = CreateSizesRegBase(selfContiguous, scales, uniqueExecutor.get());
274	        CHECK_RET(sizes != nullptr, ACLNN_ERR_INNER_NULLPTR);
275	        // 不必转到5HD，直接执行L0算子 带scales参数
276	        const aclTensor* resizeRet = nullptr;
277	        if (strncmp(mode, "nearest", strlen("nearest")) == 0) {
278	            resizeRet = l0op::ResizeNearestNeighborV2(selfContiguous, sizes, nullptr, false, false, outContiguous,
279	                                                      uniqueExecutor.get());
280	        } else {
281	            resizeRet = l0op::ResizeBilinearV2With4d(selfContiguous, sizes, false, nullptr, outContiguous,
282	                                                     uniqueExecutor.get());
283	        }
284	        CHECK_RET(resizeRet != nullptr, ACLNN_ERR_INNER_NULLPTR);
285	
286	        // 将计算结果拷贝到输出输出上
287	        auto viewCopyResult = l0op::ViewCopy(resizeRet, out, uniqueExecutor.get());
288	        CHECK_RET(viewCopyResult != nullptr, ACLNN_ERR_INNER_NULLPTR);
289	    } else {
290	        auto sizes = CreateSizesV35(out, uniqueExecutor.get());
291	        CHECK_RET(sizes != nullptr, ACLNN_ERR_INNER_NULLPTR);
292	        auto selfData = l0op::TransDataSpecial(selfContiguous, Format::FORMAT_NC1HWC0, 0, uniqueExecutor.get());
293	        CHECK_RET(selfData != nullptr, ACLNN_ERR_INNER_NULLPTR);
294	
295	        auto outData = l0op::TransDataSpecial(outContiguous, Format::FORMAT_NC1HWC0, 0, uniqueExecutor.get());
296	        CHECK_RET(outData != nullptr, ACLNN_ERR_INNER_NULLPTR);
297	
298	        // 执行L0算子
299	        const aclTensor* resizeRet = nullptr;
300	        if (strncmp(mode, "nearest", strlen("nearest")) == 0) {
301	            resizeRet = l0op::ResizeNearestNeighborV2(selfData, sizes, nullptr, false, false, outData,
302	                                                      uniqueExecutor.get());
303	        } else if (strncmp(mode, "bilinear", strlen("bilinear")) == 0) {
304	            resizeRet = l0op::ResizeBilinearV2(selfData, sizes, false, outData, uniqueExecutor.get());
305	        }
306	
307	        CHECK_RET(resizeRet != nullptr, ACLNN_ERR_INNER_NULLPTR);
308	
309	        // 输出转NCHW
310	        auto outRet = l0op::TransData(resizeRet, self->GetStorageFormat(), 0, uniqueExecutor.get());
311	        CHECK_RET(outRet != nullptr, ACLNN_ERR_INNER_NULLPTR);
312	        // 将计算结果拷贝到输出输出上
313	        auto viewCopyResult = l0op::ViewCopy(outRet, out, uniqueExecutor.get());
314	        CHECK_RET(viewCopyResult != nullptr, ACLNN_ERR_INNER_NULLPTR);
315	    }
316	
317	    // 获取计算过程中需要使用的workspace大小
318	    *workspaceSize = uniqueExecutor->GetWorkspaceSize();
319	    uniqueExecutor.ReleaseTo(executor);
320	    return ACLNN_SUCCESS;
321	}
322	
323	aclnnStatus aclnnResize(void* workspace, uint64_t workspaceSize, aclOpExecutor* executor, aclrtStream stream)
324	{
325	    L2_DFX_PHASE_2(aclnnResize);
326	    return CommonOpExecutorRun(workspace, workspaceSize, executor, stream);
327	}
328	
329	#ifdef __cplusplus
330	}
331	#endif
332

