205	static aclnnStatus CheckArrayDataAvgPoolBackWard(const aclIntArray* kernelSize, const aclIntArray* stride,
206	                                                 const aclIntArray* padding)
207	{
208	    for (uint64_t i = 0; i < kernelSize->Size(); i++) {
209	        auto size = (*kernelSize)[i];
210	        if (size <= 0) {
211	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "kernelSize [%lu] data [%li] is less than or equal to 0", i, size);
212	            return ACLNN_ERR_PARAM_INVALID;
213	        }
214	    }
215	
216	    for (uint64_t i = 0; i < stride->Size(); i++) {
217	        auto size = (*stride)[i];
218	        if (size <= 0) {
219	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "stride [%lu] data [%li] is less than or equal to 0", i, size);
220	            return ACLNN_ERR_PARAM_INVALID;
221	        }
222	    }
223	
224	    if (kernelSize->Size() != padding->Size()) {
225	        return ACLNN_ERR_PARAM_INVALID;
226	    }
227	
228	    for (uint64_t i = 0; i < kernelSize->Size(); i++) {
229	        auto halfKsize = (*kernelSize)[i] / 2;
230	        auto padSize = (*padding)[i];
231	        if (halfKsize < padSize) {
232	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "padding [%lu] data [%li] should less than kernelSize / 2 [%ld]", i,
233	                    padSize, halfKsize);
234	            return ACLNN_ERR_PARAM_INVALID;
235	        }
236	        if (padSize < 0) {
237	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "padding [%lu] data [%li] is less than 0", i, padSize);
238	            return ACLNN_ERR_PARAM_INVALID;
239	        }
240	    }
241	    return ACLNN_SUCCESS;
242	}
