330	        dimD = self->GetViewShape().GetDim(DIM_TWO);
331	        dimH = self->GetViewShape().GetDim(DIM_THREE);
332	        dimW = self->GetViewShape().GetDim(DIM_FOUR);
333	    } else {
334	        dimD = self->GetViewShape().GetDim(DIM_ONE);
335	        dimH = self->GetViewShape().GetDim(DIM_TWO);
336	        dimW = self->GetViewShape().GetDim(DIM_THREE);
337	    }
338	}
339	
340	static inline bool CheckOutputSizeValid(const aclIntArray* outputSize, int64_t dimD, int64_t dimH, int64_t dimW)
341	{
342	    int64_t outputTotal = (*outputSize)[DIM_ZERO] * (*outputSize)[DIM_ONE] * (*outputSize)[DIM_TWO];
343	    int64_t inputTotal = dimD * dimH * dimW;
344	
345	    OP_CHECK(outputTotal >= inputTotal,
346	             OP_LOGE(ACLNN_ERR_PARAM_INVALID,
347	                     "The output dimensions are of size %ld x %ld x %ld, "
348	                     "should be greater than or equal to self of size %ld x %ld x %ld.",
349	                     (*outputSize)[DIM_ZERO], (*outputSize)[DIM_ONE], (*outputSize)[DIM_TWO], dimD, dimH, dimW),
350	             return false);
351	    return true;
352	}
353	
354	static inline bool CheckIntArrayShapeMaxUnPool3D(const aclTensor* self, const aclIntArray* outputSize,
355	                                                 const aclIntArray* stride, const aclIntArray* padding)
356	{
357	    constexpr int64_t EXPECT_SIZE = 3;
358	
359	    if (!CheckArraySize3(outputSize, "output_size") || !CheckArraySize3(stride, "stride") ||
360	        !CheckArraySize3(padding, "padding")) {
361	        return false;
362	    }
363	
364	    if (!CheckPositiveValues(stride, "strides", EXPECT_SIZE) ||
365	        !CheckPositiveValues(outputSize, "outputSize", EXPECT_SIZE)) {
366	        return false;
367	    }
368	
369	    int64_t dimD, dimH, dimW;
370	    GetSpatialDimensions(self, dimD, dimH, dimW);
371	
372	    return CheckOutputSizeValid(outputSize, dimD, dimH, dimW);
373	}
374	
375	static void CalculateValuesSliceUpper(const aclTensor* self, int64_t& dim, int64_t& start, int64_t& end)
376	{
377	    if (dim < 0) {
378	        dim = dim + self->GetViewShape().GetDimNum();
379	    }
380	    if (start < 0) {
381	        start = start + self->GetViewShape().GetDim(dim);
382	    }
383	    if (end < 0) {
384	        end = end + self->GetViewShape().GetDim(dim);
385	    }
386	}
387	
388	static void CalculateValuesSliceLower(const aclTensor* self, int64_t& dim, int64_t& start, int64_t& end)
389	{
390	    if (start < 0) {
391	        start = 0;
392	    } else if (start >= self->GetViewShape().GetDim(dim)) {
393	        start = self->GetViewShape().GetDim(dim);
394	    }
395	    if (end < start) {
396	        end = start;
397	    } else if (end >= self->GetViewShape().GetDim(dim)) {
398	        end = self->GetViewShape().GetDim(dim);
399	    }
400	}
401	
402	static bool CheckDimValueWithUnique(const aclTensor* self, int64_t dim)
403	{
404	    int64_t dimSize = self->GetViewShape().GetDimNum();
405	    int64_t dimMin = std::min(-1 * dimSize, dimSize - 1);
406	    int64_t dimMax = std::max(-1 * dimSize, dimSize - 1);
407	    if (dim > dimMax || dim < dimMin) {
408	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "The param of dim must be in the range of [%ld, %ld], but got %ld.", dimMin,
409	                dimMax, dim);
410	        return false;
411	    }
412	    return true;
413	}
414	
415	} // namespace op
416	#ifdef __cplusplus
417	}
418	#endif
419	#endif // CV_COMMON_LEVEL2_BASE_H_
