#ifndef CV_COMMON_LEVEL2_BASE_H_
#define CV_COMMON_LEVEL2_BASE_H_

#include <stdio.h>
#include "op_api/op_api_def.h"
#include "op_api/aclnn_check.h"
#include "aclnn/aclnn_base.h"

#ifdef __cplusplus
extern "C" {
