39	// 根据芯片类型、dtype判断算子是否支持走aicore
40	static bool IsAiCoreSupport(const aclTensor* self)
41	{
42	    if (IsRegBase()) {
43	        return CheckType(self->GetDataType(), AICORE_DTYPE_SUPPORT_LIST_REGBASE);
44	    }
45	
46	    // ResizeBilinearV2只需要判断dtype
47	    return CheckType(self->GetDataType(), AICORE_DTYPE_SUPPORT_LIST);
48	}
