50	// AICPU算子kernel
51	static const aclTensor* ResizeBilinearV2AICPU(const aclTensor* x, const aclTensor* size, const bool align_corners,
52	                                              const aclTensor* y, aclOpExecutor* executor)
53	{
54	    L0_DFX(ResizeBilinearV2AICPU, x, size, align_corners, y);
55	    const bool half_pixel_centers = !align_corners;
56	
57	    // tf ResizeBilinear only support float output and format NHWC
58	    aclTensor* out = executor->AllocTensor(y->GetViewShape(), op::DataType::DT_FLOAT, y->GetViewFormat());
59	    if (out == nullptr) {
60	        OP_LOGE(ACLNN_ERR_INNER_NULLPTR, "alloc out tensor failed.");
61	        return nullptr;
62	    }
63	
64	    static internal::AicpuTaskSpace space("ResizeBilinear", ge::DEPEND_IN_SHAPE, true);
65	    auto ret = ADD_TO_LAUNCHER_LIST_AICPU(ResizeBilinearV2, OP_ATTR_NAMES({"T", "align_corners", "half_pixel_centers"}),
66	                                          OP_INPUT(x, size), OP_OUTPUT(out),
67	                                          OP_ATTR(x->GetDataType(), align_corners, half_pixel_centers));
68	    CHECK_RET(ret == ACLNN_SUCCESS, nullptr);
69	    return out;
